const uid=()=>crypto.randomUUID(),num=v=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}),gradeTone=v=>v<7?'red':v<=8?'yellow':v<10?'green':'blue',gradeLabel=v=>v<7?'Precisa de atenção':v<=8?'Na média':v<10?'Bom desempenho':'Excelente';
const mean=c=>usesOfficialGrade(c)?(Number.isFinite(c.officialGrade)?c.officialGrade:null):c.scores?.length?c.scores.reduce((a,s)=>a+s.value,0)/c.scores.length:null;
let demoMode=false,datasetGeneration=0;
