const activeCourses=()=>state.courses.filter(c=>!c.archived),activeMaterials=()=>state.materials.filter(m=>!m.archived&&m.category!=='community'),teacher=c=>state.teachers.find(t=>t.id===c.teacherId)?.name||'A definir';
function toast(s){window.toast(s)}
async function load(){if(state)return;if(loadPromise)return loadPromise;const generation=datasetGeneration,mode=demoMode;loadPromise=(async()=>{const r=await fetch(mode?'/api/myid/demo':'/api/myedi/data',{credentials:'same-origin'});if(!r.ok)throw Error(r.status===401?'Entre na sua conta para acessar o MyID.':'Não foi possível carregar seus dados.');const data=await r.json();if(generation!==datasetGeneration)return;state=data.state;state.lessons=state.lessons||[];state.attendance=state.attendance||[];revision=data.revision;canAdmin=data.canAdmin;readOnly=data.readOnly===true;})().finally(()=>{if(generation===datasetGeneration)loadPromise=null});return loadPromise}
async function change(fn,message='Alterações salvas.'){if(readOnly){toast('Acesso de visualização.');return false}if(saving){toast('Aguarde o salvamento atual.');return false}const next=structuredClone(state);fn(next);saving=true;const status=q('#edi-save-status');if(status)status.textContent='Salvando…';try{const r=await fetch('/api/myedi/data',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:next,revision})});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível salvar.');state=next;revision=data.revision;if(message)toast(message);return true}catch(err){toast(err.message);return false}finally{saving=false;if(q('#edi-save-status'))q('#edi-save-status').textContent='Salvo na plataforma'}}
const top=(title,subtitle='',actions='')=>`<div class="edi-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="edi-heading-actions">${actions}</div></div>`;
